'use client';

import { CreateManagerProvider } from '@/components/store/create';
import { SubscriptionModal } from '@/components/ui/pricing-modal';
import { NonProjectSettingsModal } from '@/components/ui/settings-modal/non-project';
import { ExternalRoutes } from '@/utils/constants';
import { AuthModal } from './_components/auth-modal';
import { Hero } from './_components/hero';
import { ContributorSection } from './_components/landing-page/contributor-section';
import { CTASection } from './_components/landing-page/cta-section';
import { FAQSection } from './_components/landing-page/faq-section';
import { ResponsiveMockupSection } from './_components/landing-page/responsive-mockup-section';
import { TestimonialsSection } from './_components/landing-page/testimonials-section';
import { WhatCanOnlookDoSection } from './_components/landing-page/what-can-onlook-do-section';
import { WebsiteLayout } from './_components/website-layout';

export default function Main() {
    return (
        <CreateManagerProvider>
            <WebsiteLayout showFooter={true}>
                <div className="w-screen h-screen flex items-center justify-center" id="hero">
                    <Hero />
                </div>
                <ResponsiveMockupSection />
                {/* <CodeOneToOneSection /> */}
                <WhatCanOnlookDoSection />
                {/* <ObsessForHoursSection /> */}
                <ContributorSection />
                <TestimonialsSection />
                <FAQSection />
                <CTASection href={ExternalRoutes.BOOK_DEMO} />
                <AuthModal />
                <NonProjectSettingsModal />
                <SubscriptionModal />
            </WebsiteLayout >
        </CreateManagerProvider>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { motion } from 'motion/react';

import { Button } from '@onlook/ui/button';
import { Icons } from '@onlook/ui/icons';

import { ExternalRoutes } from '@/utils/constants';
import { vujahdayScript } from '../../fonts';
import { CreateError } from './create-error';
import { HighDemand } from './high-demand';
import { MobileEmailCapture } from './mobile-email-capture';
import { UnicornBackground } from './unicorn-background';

export function Hero() {
    const [isShortScreen, setIsShortScreen] = useState(false);

    useEffect(() => {
        const checkScreenHeight = () => {
            setIsShortScreen(window.innerHeight < 700);
        };

        checkScreenHeight();
        window.addEventListener('resize', checkScreenHeight);

        return () => window.removeEventListener('resize', checkScreenHeight);
    }, []);

    return (
        <div className="relative flex h-full w-full flex-col items-center text-center text-lg">
            <UnicornBackground />
            {/* pointer-events-none allows mouse events to pass through to the canvas behind */}
            <div className="pointer-events-none mb-42 flex h-full w-full flex-col items-center justify-center gap-10 pt-12">
                <div className="relative z-20 flex flex-col items-center gap-3 pt-8 pb-2">
                    {!isShortScreen && (
                        <motion.div
                            className="relative z-20 mb-6 flex flex-col items-center gap-3 pt-4 pb-2"
                            initial={{ opacity: 0, y: -10 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ duration: 0.6, delay: 1.2, ease: 'easeOut' }}
                        >
                            <a
                                href="https://www.ycombinator.com/companies/onlook/jobs/e4gHv1n-founding-engineer-fullstack"
                                target="_blank"
                                rel="noopener noreferrer"
                                className="pointer-events-auto hover:bg-foreground-secondary/20 border-foreground-secondary/20 text-foreground-secondary inline-flex items-center gap-2 rounded-full border px-3 py-1.5 text-xs backdrop-blur-sm transition-all duration-200 hover:scale-102"
                            >
                                We're hiring engineers
                                <Icons.ArrowRight className="h-4 w-4" />
                            </a>
                        </motion.div>
                    )}
                    <motion.h1
                        className="text-center text-6xl !leading-[0.9] leading-tight font-light"
                        initial={{ opacity: 0, filter: 'blur(4px)' }}
                        animate={{ opacity: 1, filter: 'blur(0px)' }}
                        transition={{ duration: 0.6, ease: 'easeOut' }}
                        style={{ willChange: 'opacity, filter', transform: 'translateZ(0)' }}
                    >
                        Cursor for
                        <br />
                        <span
                            className={`font-normal italic ${vujahdayScript.className} ml-1 text-[4.6rem] leading-[1.0]`}
                        >
                            Designers
                        </span>
                    </motion.h1>
                    <motion.p
                        className="text-foreground-secondary mt-2 max-w-xl text-center text-lg text-balance"
                        initial={{ opacity: 0, filter: 'blur(4px)' }}
                        animate={{ opacity: 1, filter: 'blur(0px)' }}
                        transition={{ duration: 0.6, delay: 0.15, ease: 'easeOut' }}
                        style={{ willChange: 'opacity, filter', transform: 'translateZ(0)' }}
                    >
                        Design with your real components.
                        <br />
                        Ship PRs, not prototypes.
                    </motion.p>
                    <HighDemand />
                    <CreateError />
                </div>
                <div className="pointer-events-auto relative z-20 hidden flex-row items-center gap-4 sm:flex">
                    <motion.div
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.6, delay: 0.4, ease: 'easeOut' }}
                    >
                        <Button
                            asChild
                            className="bg-foreground-primary text-background-primary hover:bg-foreground-hover"
                        >
                            <a
                                href={ExternalRoutes.BOOK_DEMO}
                                target="_blank"
                                rel="noopener noreferrer"
                            >
                                Book a Demo
                                <Icons.ArrowRight className="h-4 w-4" />
                            </a>
                        </Button>
                    </motion.div>
                </div>
                <div className="pointer-events-auto w-full flex justify-center">
                    <MobileEmailCapture />
                </div>
            </div>
        </div>
    );
}

import { useCreateManager } from '@/components/store/create';
import { observer } from 'mobx-react-lite';
import { motion } from 'motion/react';

export const CreateError = observer(() => {
    const createManager = useCreateManager();
    const error = createManager.error;

    return (
        <motion.p
            className="max-w-xl text-center mt-2 p-2 bg-red-900/80 rounded-xl border border-red-500 text-sm text-red-500 px-4"
            initial={{ opacity: 0, filter: "blur(4px)" }}
            animate={error ? { opacity: 1, filter: "blur(0px)" } : { opacity: 0, filter: "blur(4px)" }}
            transition={{ duration: 0.6, delay: 0.15, ease: "easeOut" }}
            style={{ willChange: "opacity, filter", transform: "translateZ(0)", display: error ? 'block' : 'none' }}
        >
            {error}
        </motion.p>
    );
});

import { motion } from 'motion/react';

export function HighDemand() {
    // TODO: Use feature flags
    const isHighDemand = false;

    if (!isHighDemand) {
        return null;
    }

    return (
        <motion.p
            className="max-w-xl text-center mt-2 p-2 bg-amber-900/80 rounded-xl border border-amber-300 text-sm text-amber-300 px-4"
            initial={{ opacity: 0, filter: "blur(4px)" }}
            animate={{ opacity: 1, filter: "blur(0px)" }}
            transition={{ duration: 0.6, delay: 0.15, ease: "easeOut" }}
            style={{ willChange: "opacity, filter", transform: "translateZ(0)" }}
        >
            {"We're currently experiencing high demand. Project may fail to create."}
        </motion.p>
    );
}

'use client';

import { Button } from '@onlook/ui/button';
import { Icons } from '@onlook/ui/icons/index';
import { Input } from '@onlook/ui/input';
import { motion } from 'motion/react';
import React, { useCallback, useEffect, useRef, useState } from 'react';

interface FormData {
    name: string;
    email: string;
    utm_source: string;
    utm_medium: string;
    utm_campaign: string;
    utm_term: string;
    utm_content: string;
}

// Constants for better maintainability
const MEASUREMENT_DELAY = 100; // ms - delay for DOM measurement
const SUCCESS_TIMEOUT = 7000; // ms - how long to show success message

export function MobileEmailCapture() {
    const [showEmailForm, setShowEmailForm] = useState(false);
    const [containerHeight, setContainerHeight] = useState<number>(140); // Increased default height for notification
    const notificationRef = useRef<HTMLDivElement>(null);
    const formRef = useRef<HTMLDivElement>(null);
    const nameInputRef = useRef<HTMLInputElement>(null);
    const emailInputRef = useRef<HTMLInputElement>(null);
    const successTimeoutRef = useRef<NodeJS.Timeout | null>(null);
    const measurementTimerRef = useRef<NodeJS.Timeout | null>(null);
    const resizeTimerRef = useRef<NodeJS.Timeout | null>(null);
    const initialUtmsRef = useRef<{
        utm_source: string;
        utm_medium: string;
        utm_campaign: string;
        utm_term: string;
        utm_content: string;
    } | null>(null);
    const [formData, setFormData] = useState<FormData>({
        name: '',
        email: '',
        utm_source: '',
        utm_medium: '',
        utm_campaign: '',
        utm_term: '',
        utm_content: ''
    });
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [showSuccess, setShowSuccess] = useState(false);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (typeof window !== 'undefined' && initialUtmsRef.current === null) {
            const urlParams = new URLSearchParams(window.location.search);
            const utmValues = {
                utm_source: urlParams.get('utm_source') || '',
                utm_medium: urlParams.get('utm_medium') || '',
                utm_campaign: urlParams.get('utm_campaign') || '',
                utm_term: urlParams.get('utm_term') || '',
                utm_content: urlParams.get('utm_content') || ''
            };

            // Cache initial UTM values for the entire session
            initialUtmsRef.current = utmValues;

            setFormData(prev => ({
                ...prev,
                ...utmValues
            }));
        }
    }, []);

    const handleInputChange = (field: keyof FormData, value: string) => {
        setFormData(prev => ({ ...prev, [field]: value }));
        setError(null);
    };

    // Email validation function
    const isValidEmail = (email: string): boolean => {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email.trim());
    };

    // Handle Enter key press in name field
    const handleNameKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            emailInputRef.current?.focus();
        }
    };

    // Handle Enter key press in email field
    const handleEmailKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            if (isValidEmail(formData.email) && formData.name.trim()) {
                handleSubmit(e);
            }
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!formData.name.trim() || !formData.email.trim()) {
            setError('Please fill in all fields');
            return;
        }

        if (!isValidEmail(formData.email)) {
            setError('Please enter a valid email address');
            return;
        }

        setIsSubmitting(true);
        setError(null);

        try {
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout

            const response = await fetch('/api/email-capture', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    name: formData.name.trim(),
                    email: formData.email.trim(),
                    utm_source: formData.utm_source,
                    utm_medium: formData.utm_medium,
                    utm_campaign: formData.utm_campaign,
                    utm_term: formData.utm_term,
                    utm_content: formData.utm_content,
                }),
                signal: controller.signal,
            });

            clearTimeout(timeoutId);

            const result = await response.json();

            if (!response.ok) {
                throw new Error(result.error || `Server error (${response.status})`);
            }

            setShowSuccess(true);
            successTimeoutRef.current = setTimeout(() => {
                setShowSuccess(false);
                setFormData({
                    name: '',
                    email: '',
                    // Restore UTM values from initial cache instead of clearing
                    ...(initialUtmsRef.current || {
                        utm_source: '',
                        utm_medium: '',
                        utm_campaign: '',
                        utm_term: '',
                        utm_content: ''
                    })
                });
                setShowEmailForm(false);
                successTimeoutRef.current = null;
            }, SUCCESS_TIMEOUT);

        } catch (error) {
            console.error('Failed to submit email capture form:', error);

            if (error instanceof Error) {
                if (error.name === 'AbortError') {
                    setError('Request timed out. Please check your connection and try again.');
                } else if (error.message.includes('Server error')) {
                    setError('Server error. Please try again in a moment.');
                } else if (error.message.includes('Failed to fetch')) {
                    setError('Network error. Please check your connection and try again.');
                } else {
                    setError('Failed to submit form. Please try again.');
                }
            } else {
                setError('An unexpected error occurred. Please try again.');
            }
        } finally {
            setIsSubmitting(false);
        }
    };

    const measureAndSetHeight = useCallback(() => {
        try {
            if (showEmailForm && formRef.current) {
                const height = formRef.current.scrollHeight;
                // Add extra padding when error is present to ensure error message is visible
                const extraPadding = 32;
                setContainerHeight(Math.max(height + extraPadding, 100));
            } else if (!showEmailForm && notificationRef.current) {
                const height = notificationRef.current.scrollHeight;
                setContainerHeight(Math.max(height + 32, 100)); // Add padding and ensure minimum height
            }
        } catch (error) {
            console.warn('Failed to measure container height:', error);
            // Fallback to default height if measurement fails
            setContainerHeight(140);
        }
    }, [showEmailForm, error]);

    // Debounced measurement function to prevent race conditions
    const debouncedMeasurement = useCallback(() => {
        // Clear any existing measurement timer
        if (measurementTimerRef.current) {
            clearTimeout(measurementTimerRef.current);
        }

        measurementTimerRef.current = setTimeout(() => {
            measureAndSetHeight();
            measurementTimerRef.current = null;
        }, MEASUREMENT_DELAY);
    }, [measureAndSetHeight]);

    // Measure height whenever showEmailForm or error changes
    useEffect(() => {
        debouncedMeasurement();
    }, [debouncedMeasurement]);

    // Also measure on window resize
    useEffect(() => {
        const handleResize = () => {
            // Clear any existing resize timer
            if (resizeTimerRef.current) {
                clearTimeout(resizeTimerRef.current);
            }

            resizeTimerRef.current = setTimeout(() => {
                measureAndSetHeight();
                resizeTimerRef.current = null;
            }, MEASUREMENT_DELAY);
        };

        window.addEventListener('resize', handleResize);
        return () => {
            window.removeEventListener('resize', handleResize);
            if (resizeTimerRef.current) {
                clearTimeout(resizeTimerRef.current);
                resizeTimerRef.current = null;
            }
        };
    }, [measureAndSetHeight]);

    // Cleanup all timers on unmount
    useEffect(() => {
        return () => {
            if (successTimeoutRef.current) {
                clearTimeout(successTimeoutRef.current);
                successTimeoutRef.current = null;
            }
            if (measurementTimerRef.current) {
                clearTimeout(measurementTimerRef.current);
                measurementTimerRef.current = null;
            }
            if (resizeTimerRef.current) {
                clearTimeout(resizeTimerRef.current);
                resizeTimerRef.current = null;
            }
        };
    }, []);

    // Focus the name input when form opens
    useEffect(() => {
        if (showEmailForm && nameInputRef.current) {
            const timer = setTimeout(() => {
                nameInputRef.current?.focus();
            }, 100); // Small delay to ensure the form is fully rendered
            return () => clearTimeout(timer);
        }
    }, [showEmailForm]);

    const handleShowEmailForm = () => {
        setShowEmailForm(true);
    };

    const handleClose = () => {
        if (!isSubmitting) {
            // Clear all timers if they exist
            if (successTimeoutRef.current) {
                clearTimeout(successTimeoutRef.current);
                successTimeoutRef.current = null;
            }
            if (measurementTimerRef.current) {
                clearTimeout(measurementTimerRef.current);
                measurementTimerRef.current = null;
            }
            if (resizeTimerRef.current) {
                clearTimeout(resizeTimerRef.current);
                resizeTimerRef.current = null;
            }

            setFormData({
                name: '',
                email: '',
                // Restore UTM values from initial cache instead of clearing
                ...(initialUtmsRef.current || {
                    utm_source: '',
                    utm_medium: '',
                    utm_campaign: '',
                    utm_term: '',
                    utm_content: ''
                })
            });
            setError(null);
            setShowSuccess(false);
            setShowEmailForm(false);
        }
    };

    return (
        <motion.div
            className="sm:hidden text-balance flex flex-col gap-3 items-center relative z-20 mx-4 xs:mx-6 text-foreground-secondary bg-foreground-secondary/10 backdrop-blur-lg rounded-lg border-[0.5px] border-foreground-secondary/20 p-3 xs:p-4 w-full max-w-[calc(100vw-2rem)] xs:max-w-sm select-none"
            initial={{ opacity: 0, filter: "blur(4px)" }}
            animate={{
                opacity: 1,
                filter: "blur(0px)",
                height: containerHeight
            }}
            transition={{
                duration: 0.6,
                delay: 0.6,
                ease: "easeOut",
                height: { duration: 0.4, ease: "easeInOut" }
            }}
            style={{ willChange: "opacity, filter", transform: "translateZ(0)" }}
        >
            {!showEmailForm ? (
                <motion.div
                    key="notification"
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -20 }}
                    transition={{ duration: 0.3, ease: "easeInOut" }}
                    className="flex flex-col gap-3 items-center w-full"
                    ref={notificationRef}
                >
                    <div className="text-center text-base xs:text-lg font-light my-2 text-foreground-secondary px-2">
                        Onlook is optimized for larger screens
                    </div>
                    <Button
                        size="sm"
                        onClick={handleShowEmailForm}
                        className="bg-foreground-primary text-background-primary w-full hover:bg-foreground-hover hover:text-background-primary h-auto py-3 text-base xs:text-lg whitespace-normal leading-tight"
                    >
                        Email me a link for later
                    </Button>
                </motion.div>
            ) : (
                <motion.div
                    key="email-form"
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -20 }}
                    transition={{ duration: 0.3, ease: "easeInOut" }}
                    className="flex flex-col gap-3 items-center w-full"
                    ref={formRef}
                >
                    {showSuccess ? (
                        <motion.div
                            className="flex flex-col items-center justify-center gap-3 py-6"
                            initial={{ opacity: 0, height: 0 }}
                            animate={{ opacity: 1, height: "auto" }}
                            exit={{ opacity: 0, height: 0 }}
                            transition={{ duration: 0.4, ease: "easeInOut" }}
                            layout
                            layoutId="success-content"
                        >
                            <Icons.Check className="size-8" />
                            <div className="text-foreground-secondary text-base xs:text-lg font-light w-full px-2">
                                Thanks, an email to use Onlook has been sent to you!
                            </div>
                        </motion.div>
                    ) : (
                        <>
                            <div className="text-left text-foreground-secondary text-sm xs:text-base font-light w-full px-1">
                                <h3 className="text-sm xs:text-base font-medium text-foreground-primary break-words">
                                    Email me a link to Onlook
                                </h3>
                            </div>

                            <form onSubmit={handleSubmit} className="space-y-2 w-full">
                                <div className="space-y-1 text-left">
                                    <label htmlFor="name" className="text-xs text-foreground-secondary">
                                        Name
                                    </label>
                                    <Input
                                        ref={nameInputRef}
                                        id="name"
                                        type="text"
                                        placeholder="Pablo Picasso"
                                        value={formData.name}
                                        onChange={(e) => handleInputChange('name', e.target.value)}
                                        onKeyDown={handleNameKeyDown}
                                        disabled={isSubmitting}
                                        required
                                        className="bg-background-primary/50 border-foreground-secondary/20 text-sm h-9 xs:h-10 text-foreground-primary focus:ring-0 focus-visible:ring-0 !ring-0 focus:border-foreground-primary select-text w-full"
                                    />
                                </div>

                                <div className="space-y-1 text-left">
                                    <label htmlFor="email" className="text-xs text-foreground-secondary">
                                        Email
                                    </label>
                                    <Input
                                        ref={emailInputRef}
                                        id="email"
                                        type="email"
                                        placeholder="Enter your email"
                                        value={formData.email}
                                        onChange={(e) => handleInputChange('email', e.target.value)}
                                        onKeyDown={handleEmailKeyDown}
                                        disabled={isSubmitting}
                                        required
                                        className="bg-background-primary/50 border-foreground-secondary/20 text-sm h-9 xs:h-10 text-foreground-primary focus:ring-0 focus-visible:ring-0 !ring-0 focus:border-foreground-primary select-text w-full"
                                    />
                                </div>

                                {/* Hidden UTM parameter fields */}
                                <input type="hidden" name="utm_source" value={formData.utm_source} />
                                <input type="hidden" name="utm_medium" value={formData.utm_medium} />
                                <input type="hidden" name="utm_campaign" value={formData.utm_campaign} />
                                <input type="hidden" name="utm_term" value={formData.utm_term} />
                                <input type="hidden" name="utm_content" value={formData.utm_content} />

                                {error && (
                                    <motion.div
                                        className="text-sm text-red-500 text-center"
                                        initial={{ opacity: 0 }}
                                        animate={{ opacity: 1 }}
                                        transition={{ duration: 0.2 }}
                                    >
                                        {error}
                                    </motion.div>
                                )}

                                <div className="pt-1 flex gap-2">
                                    <Button
                                        type="button"
                                        variant="outline"
                                        onClick={handleClose}
                                        disabled={isSubmitting}
                                        className="border-foreground-secondary/20 text-foreground-secondary hover:bg-foreground-secondary/10 h-9 xs:h-10 w-9 xs:w-10 rounded-md p-0 flex-shrink-0"
                                    >
                                        <Icons.CrossL className="w-3 xs:w-4 h-3 xs:h-4" />
                                    </Button>
                                    <Button
                                        type="submit"
                                        disabled={isSubmitting || !formData.name.trim() || !isValidEmail(formData.email)}
                                        className="flex-1 bg-foreground-primary text-background-primary hover:bg-foreground-hover hover:text-background-primary h-9 xs:h-10 text-xs xs:text-sm disabled:opacity-50 disabled:cursor-not-allowed min-w-0"
                                    >
                                        <span className="truncate">
                                            {isSubmitting ? 'Submitting...' : 'Email me a link'}
                                        </span>
                                    </Button>
                                </div>
                            </form>
                        </>
                    )}
                </motion.div>
            )}
        </motion.div>
    );
}

'use client';

import './contributor.css';

import { Icons } from '@onlook/ui/icons';
import Link from 'next/link';
import { useEffect, useState } from 'react';

interface Contributor {
    login: string;
    avatar_url: string;
    id: number;
}

// Floating Circles: two concentric rings
const FloatingRings = () => {
    const [isMd, setIsMd] = useState(false);
    const [contributors, setContributors] = useState<Contributor[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
        const media = window.matchMedia('(min-width: 768px)');
        const listener = () => setIsMd(media.matches);
        media.addEventListener('change', listener);
        setIsMd(media.matches);
        return () => media.removeEventListener('change', listener);
    }, []);

    useEffect(() => {
        const fetchContributors = async () => {
            try {
                const response = await fetch('https://api.github.com/repos/onlook-dev/onlook/contributors?per_page=100');
                if (!response.ok) {
                    throw new Error('Failed to fetch contributors');
                }
                const data = await response.json();
                const filteredContributors = data.filter((contributor: Contributor) => {
                    return contributor.avatar_url && !contributor.login.includes('[bot]');
                });
                setContributors(filteredContributors);
            } catch (error) {
                console.error('Failed to fetch contributors:', error);
            } finally {
                setIsLoading(false);
            }
        };

        fetchContributors();
    }, []);

    if (!mounted) {
        return null;
    }

    // Tighter radii for mobile
    const innerRadius = isMd ? 260 * 1.4 : 260;
    const outerRadius = isMd ? 340 * 1.4 : 380;
    const size = 840;
    const center = size / 2;

    // Number of faces in each ring
    const innerRingCount = isMd ? 24 : Math.floor(24 * 0.6);
    const outerRingCount = isMd ? 30 : Math.floor(30 * 0.6);

    return (
        <div
            className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 aspect-square pointer-events-none"
            style={{ width: size, height: size }}
        >
            {/* Inner ring (clockwise) */}
            <div className="absolute left-1/2 top-1/2 w-full h-full spin-normal">
                {Array.from({ length: innerRingCount }).map((_, i) => {
                    const angle = (i / innerRingCount) * 2 * Math.PI;
                    const x = center + Math.cos(angle) * innerRadius;
                    const y = center + Math.sin(angle) * innerRadius;
                    const contributor = !isLoading && contributors.length > 0 ? contributors[i % contributors.length] : null;
                    return (
                        <div
                            key={`inner-${i}`}
                            className="absolute rounded-full bg-white/20 border border-foreground-primary/40 border-[0.5px] shadow-lg overflow-hidden counter-spin"
                            style={{
                                width: '56px',
                                height: '56px',
                                left: `${x - 28}px`,
                                top: `${y - 28}px`,
                                transformOrigin: 'center center'
                            }}
                        >
                            {contributor && (
                                <img
                                    src={contributor.avatar_url}
                                    alt={`${contributor.login}'s avatar`}
                                    className="w-full h-full object-cover"
                                    loading="lazy"
                                />
                            )}
                        </div>
                    );
                })}
            </div>
            {/* Outer ring */}
            <div className="absolute left-1/2 top-1/2 w-full h-full spin-reverse">
                {Array.from({ length: outerRingCount }).map((_, i) => {
                    const angle = (i / outerRingCount) * 2 * Math.PI;
                    const x = center + Math.cos(angle) * outerRadius;
                    const y = center + Math.sin(angle) * outerRadius;
                    const contributorIndex = (i + innerRingCount) % (contributors.length || 1);
                    const contributor = !isLoading && contributors.length > 0 ? contributors[contributorIndex] : null;
                    return (
                        <div
                            key={`outer-${i}`}
                            className="absolute rounded-full bg-white/20 border border-foreground-primary/40 border-[0.5px] shadow-lg overflow-hidden counter-spin-reverse"
                            style={{
                                width: '56px',
                                height: '56px',
                                left: `${x - 28}px`,
                                top: `${y - 28}px`,
                                transformOrigin: 'center center'
                            }}
                        >
                            {contributor && (
                                <img
                                    src={contributor.avatar_url}
                                    alt={`${contributor.login}'s avatar`}
                                    className="w-full h-full object-cover"
                                    loading="lazy"
                                />
                            )}
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

